# parse pairs
stack=[]
pairs={}
for i,c in enumerate(t):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j
ps=sorted(pairs.items())
for i,j in ps:
    if i<j:
        print(i+1,j+1)
